// Cypher demo (Neo4j Browser or cypher-shell)
CREATE (w:Product {sku:'WIDGET-1', qty:50}),
       (g:Product {sku:'GADGET-2', qty:12}),
       (c:Category {name:'Tools'}),
       (w)-[:IN_CATEGORY]->(c), (g)-[:IN_CATEGORY]->(c);
MATCH (p:Product)-[:IN_CATEGORY]->(c:Category {name:'Tools'})
WHERE p.qty < 20
RETURN p.sku, p.qty;
MATCH path = (a:Product)-[*1..2]-() RETURN path LIMIT 5;

