// Gremlin console (connect to the Neptune endpoint)
g.addV('product').property('sku','WIDGET-1').property('qty',50).as('w').
  addV('product').property('sku','GADGET-2').property('qty',12).as('g').
  addV('category').property('name','Tools').as('c').
  addE('in_category').from('w').to('c').
  addE('in_category').from('g').to('c').iterate();
g.V().has('product','qty',lt(20)).values('sku');

// Gremlin console against JanusGraph
graph = JanusGraphFactory.open('conf/janusgraph-cql-es.properties');
g = graph.traversal();
w = g.addV('product').property('sku','WIDGET-1').property('qty',50).next();
c = g.addV('category').property('name','Tools').next();
g.addE('in_category').from(w).to(c).iterate();
g.V().has('product','qty',lt(20)).values('sku').toList();

-- OrientDB SQL (Studio or console.sh)
CREATE CLASS Product EXTENDS V;
CREATE CLASS Category EXTENDS V;
CREATE PROPERTY Product.sku STRING;
INSERT INTO Product SET sku='WIDGET-1', qty=50;
INSERT INTO Product SET sku='GADGET-2', qty=12;
SELECT sku, qty FROM Product WHERE qty < 20;
TRAVERSE out('in_category') FROM (SELECT FROM Category WHERE name='Tools');

