-- InfluxDB v3 SQL
CREATE TABLE readings (time TIMESTAMP, device TAG, temp DOUBLE);
-- write via line protocol:
-- readings,device=sensor-1 temp=21.5
-- query:
SELECT date_bin(INTERVAL '1 hour', time) AS hr, device, AVG(temp)
FROM readings GROUP BY hr, device ORDER BY hr;
SELECT * FROM readings WHERE temp > 30 ORDER BY time DESC LIMIT 10;
